CREATE TABLE IF NOT EXISTS finance_permissions(user_id INTEGER NOT NULL, business_id INTEGER NOT NULL, can_view INTEGER NOT NULL DEFAULT 0, can_write INTEGER NOT NULL DEFAULT 0, can_edit INTEGER NOT NULL DEFAULT 0, can_authorize INTEGER NOT NULL DEFAULT 0, can_report INTEGER NOT NULL DEFAULT 0, can_configure INTEGER NOT NULL DEFAULT 0, can_void INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,business_id));
INSERT OR IGNORE INTO finance_permissions(user_id,business_id,can_view,can_write,can_edit,can_authorize,can_report,can_configure,can_void) SELECT u.id,b.id,1,1,1,1,1,1,1 FROM users u CROSS JOIN businesses b WHERE u.role='admin';

CREATE TABLE IF NOT EXISTS finance_settings(business_id INTEGER PRIMARY KEY, distribution_pct INTEGER NOT NULL DEFAULT 3000, reinvestment_pct INTEGER NOT NULL DEFAULT 1700, updated_by INTEGER, updated_at TEXT);
INSERT OR IGNORE INTO finance_settings(business_id) SELECT id FROM businesses;
CREATE TABLE IF NOT EXISTS finance_accounts(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,opening_balance INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,shared_reference TEXT NOT NULL DEFAULT '',UNIQUE(business_id,name));
INSERT OR IGNORE INTO finance_accounts(id,business_id,name,type) VALUES(101,1,'Efectivo','cash'),(102,1,'Nequi','wallet'),(103,1,'Bancolombia','bank'),(104,1,'Caja menor','petty_cash'),(201,2,'Efectivo','cash'),(202,2,'Nequi','wallet'),(203,2,'Bancolombia','bank'),(204,2,'Caja menor','petty_cash');
CREATE TABLE IF NOT EXISTS finance_movements(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,account_id INTEGER NOT NULL,created TEXT NOT NULL,effective_date TEXT NOT NULL,kind TEXT NOT NULL,concept TEXT NOT NULL,source_type TEXT,source_id INTEGER,direction INTEGER NOT NULL,amount INTEGER NOT NULL,balance_after INTEGER NOT NULL,user_id INTEGER NOT NULL,request_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',reversal_of INTEGER,UNIQUE(business_id,request_id));
CREATE INDEX IF NOT EXISTS idx_finance_movements_account ON finance_movements(business_id,account_id,effective_date,id);

CREATE TABLE IF NOT EXISTS finance_invoices(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,number TEXT NOT NULL,invoice_date TEXT NOT NULL,description TEXT NOT NULL,total INTEGER NOT NULL,tax INTEGER NOT NULL DEFAULT 0,supplier TEXT NOT NULL DEFAULT '',supplier_document TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',due_date TEXT,note TEXT NOT NULL DEFAULT '',attachment TEXT NOT NULL DEFAULT '',purchase_id INTEGER,status TEXT NOT NULL DEFAULT 'pending',created_by INTEGER NOT NULL,created_at TEXT NOT NULL,request_id TEXT NOT NULL,UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS finance_invoice_payments(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,invoice_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,paid_at TEXT NOT NULL,user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));

CREATE TABLE IF NOT EXISTS finance_employees(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,name TEXT NOT NULL,document TEXT NOT NULL DEFAULT '',position TEXT NOT NULL DEFAULT '',salary INTEGER NOT NULL,started TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,usual_account_id INTEGER,note TEXT NOT NULL DEFAULT '',UNIQUE(business_id,document));
CREATE TABLE IF NOT EXISTS finance_payrolls(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,employee_id INTEGER NOT NULL,period TEXT NOT NULL,days_worked INTEGER NOT NULL,base_salary INTEGER NOT NULL,bonuses INTEGER NOT NULL DEFAULT 0,advances INTEGER NOT NULL DEFAULT 0,deductions INTEGER NOT NULL DEFAULT 0,net_total INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_by INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(business_id,employee_id,period));
CREATE TABLE IF NOT EXISTS finance_payroll_payments(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,payroll_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,paid_at TEXT NOT NULL,user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));

CREATE TABLE IF NOT EXISTS finance_profits(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,period TEXT NOT NULL,profit INTEGER NOT NULL,distribution_pct INTEGER NOT NULL,reinvestment_pct INTEGER NOT NULL,distribution_fund INTEGER NOT NULL,reinvestment INTEGER NOT NULL,available_distribution INTEGER NOT NULL,remaining_profit INTEGER NOT NULL,note TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(business_id,period));
CREATE TABLE IF NOT EXISTS finance_beneficiaries(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,name TEXT NOT NULL,document TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS finance_profit_payouts(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,profit_id INTEGER NOT NULL,beneficiary_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,paid_at TEXT NOT NULL,user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS finance_reinvestment_uses(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,used_at TEXT NOT NULL,concept TEXT NOT NULL,invoice_id INTEGER,note TEXT NOT NULL DEFAULT '',user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS finance_reconciliations(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,account_id INTEGER NOT NULL,observed INTEGER NOT NULL,book_balance INTEGER NOT NULL,difference INTEGER NOT NULL,reconciled_at TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',user_id INTEGER NOT NULL);
